import com.armedia.acm.plugins.businessprocess.model.OnEnterQueueModel;
import com.armedia.acm.plugins.casefile.model.CaseFile;
import com.armedia.acm.plugins.casefile.pipeline.CaseFilePipelineContext;
import org.springframework.expression.EvaluationContext;
import org.springframework.expression.Expression;
import org.springframework.expression.ExpressionParser;
import org.springframework.expression.spel.standard.SpelExpressionParser;
import org.springframework.expression.spel.support.StandardEvaluationContext;
function Boolean evalSpring(String expression, OnEnterQueueModel model)
{
    ExpressionParser ep = new SpelExpressionParser();
    Expression exp = ep.parseExpression(expression);
    EvaluationContext ec = new StandardEvaluationContext();

    CaseFilePipelineContext context = (CaseFilePipelineContext) model.getPipelineContext();

    Boolean evaluated = exp.getValue(ec, context, Boolean.class);

    return evaluated;
}
// rule values at C19, header at C14
rule "Form Workflow Rules_19"
	salience 65535
	when
		$model: OnEnterQueueModel(eval(evalSpring("enqueueName.equals(\"next-queue\")", $model)))
	then
end
